void tree_sitter_css_external_scanner_destroy(void *);
bool tree_sitter_css_external_scanner_scan(void *, TSLexer *, const bool *);
unsigned tree_sitter_css_external_scanner_serialize(void *, char *);
void tree_sitter_css_external_scanner_deserialize(void *, const char *, unsigned);

static bool ts_external_scanner_scan(void *payload, TSLexer *lexer, const bool *states) {
  const uint8_t *bits = (const uint8_t *)states;
  bool valid[EXTERNAL_TOKEN_COUNT];
  for (unsigned i = 0; i < EXTERNAL_TOKEN_COUNT; i++) valid[i] = (bits[i / 8] >> (i % 8)) & 1;
  return tree_sitter_css_external_scanner_scan(payload, lexer, valid);
}
